import { NextResponse } from 'next/server';

export async function GET(request: Request) {
    const { searchParams } = new URL(request.url);
    const token        = searchParams.get('token');
    const refreshToken = searchParams.get('refresh_token');

    if (token) {
        const response = NextResponse.redirect(new URL('/profile', request.url));

        const isProd = process.env.NODE_ENV === 'production';

        response.cookies.set('access_token', token, {
            httpOnly: false,        
            secure: isProd,
            sameSite: 'lax',
            path: '/',
            maxAge: 60 * 60,         
        });

        if (refreshToken) {
            response.cookies.set('refresh_token', refreshToken, {
                httpOnly: true,      
                secure: isProd,
                sameSite: 'lax',
                path: '/',
                maxAge: 60 * 60 * 24 * 30,  
            });
        }

        return response;
    }

    return NextResponse.redirect(new URL('/landing', request.url));
}

import { NextResponse } from 'next/server';

const BACKEND_URL = process.env.NEXT_PUBLIC_BACKEND_API_URL || '';

const resolveProfileRedirectPath = async (token: string): Promise<string> => {
    if (!BACKEND_URL) {
        return '/profile';
    }

    try {
        const response = await fetch(`${BACKEND_URL}/api/Users/profile`, {
            headers: {
                Authorization: `Bearer ${token}`,
            },
            cache: 'no-store',
        });

        if (!response.ok) {
            return '/profile';
        }

        const data = (await response.json()) as { displayName?: unknown };
        const displayName =
            typeof data.displayName === 'string' ? data.displayName.trim() : '';

        if (!displayName) {
            return '/profile';
        }

        return `/profile/${encodeURIComponent(displayName)}`;
    } catch {
        return '/profile';
    }
};

export async function GET(request: Request) {
    const { searchParams } = new URL(request.url);
    const token        = searchParams.get('token');
    const refreshToken = searchParams.get('refresh_token');

    if (token) {
        const redirectPath = await resolveProfileRedirectPath(token);
        const response = NextResponse.redirect(new URL(redirectPath, request.url));

        const isProd = process.env.NODE_ENV === 'production';

        response.cookies.set('access_token', token, {
            httpOnly: false,        
            secure: isProd,
            sameSite: 'lax',
            path: '/',
            maxAge: 60 * 60,         
        });

        if (refreshToken) {
            response.cookies.set('refresh_token', refreshToken, {
                httpOnly: true,      
                secure: isProd,
                sameSite: 'lax',
                path: '/',
                maxAge: 60 * 60 * 24 * 30,  
            });
        }

        return response;
    }

    return NextResponse.redirect(new URL('/landing', request.url));
}

"use client";

import { Suspense } from "react";
import Header from "@/components/global/Header/Header";
import MenuSidebar from "@/components/global/MenuSidebar/MenuSidebar";
import ProfileMainView from "@/components/profile/ProfileMainView/ProfileMainView";
import ProfileSidebarRight from "@/components/profile/ProfileSidebarRight/ProfileSidebarRight";
import "./[username]/page.css";

function ProfilePageContent() {
    return (
        <div className="page-wrapper">
            <Header title="Profile" />
            <div className="feed-container">
                <MenuSidebar />
                <div className="profile-layout-main">
                    <div className="profile-layout-center">
                        <ProfileMainView />
                    </div>
                    <div className="profile-layout-right">
                        <ProfileSidebarRight />
                    </div>
                </div>
            </div>
        </div>
    );
}

export default function ProfilePage() {
    return (
        <Suspense fallback={<div className="profile-loading-fallback">Loading...</div>}>
            <ProfilePageContent />
        </Suspense>
    );
}

"use client";

import React from "react";
import Link from "next/link";
import { Home, Search, MessageSquare } from 'lucide-react';

import SidebarItemProps from "@/types/sidebar/sidebarItemProps";
import { useActiveSidebar } from "@/hooks/useActiveSidebar";
import ProfileMenu from "@/components/global/ProfileMenu/ProfileMenu";
import './MenuSidebar.css';

const MenuSidebarItem = ({ icon: Icon, label, path, badge, isActive }: SidebarItemProps & { isActive?: boolean }) => (
    <Link href={path} prefetch={false} className={`sidebaritem-link ${isActive ? 'active' : ''}`}>
        <div className="icon-wrapper">
            <Icon className="icon" size={20} strokeWidth={2.5} />
            <span className="sidebaritem-span">{label}</span>
        </div>
        {badge && <div className="sidebaritem-badge">{badge}</div>}
    </Link>
);

const MenuSidebar = () => {
    const { isActive } = useActiveSidebar();

    const handleLogout = () => {
        if (typeof window !== 'undefined') {
            window.location.href = '/';
        }
    };

    return (
        <div className="sidebar">
            <div className="sidebar-section">
                <h3 className="sidebar-header">MENU</h3>
                <div className="sidebar-items">
                    <MenuSidebarItem
                        icon={Home}
                        label="Feed"
                        path="/"
                        badge={""}
                        isActive={isActive("/")}
                    />
                    <MenuSidebarItem
                        icon={Search}
                        label="Discover"
                        path="/discovery"
                        badge={""}
                        isActive={isActive("/discovery")}
                    />
                    <MenuSidebarItem
                        icon={MessageSquare}
                        label="Messages"
                        path="/messages"
                        badge={3}
                        isActive={isActive("/messages")}
                    />
                </div>
            </div>

            <div className="sidebar-footer">
                <ProfileMenu
                    userName="test"
                    currentSong="test"
                    avatarSrc="/icons/SoundSpaceIcon.png"
                    onLogout={handleLogout}
                />
            </div>
        </div>
    );
};

export default MenuSidebar;

"use client";

import React from "react";
import Link from "next/link";
import { Home, Search, MessageSquare } from 'lucide-react';

import SidebarItemProps from "@/types/sidebar/sidebarItemProps";
import { useActiveSidebar } from "@/hooks/useActiveSidebar";
import { useUserProfile } from "@/hooks/UserProfile/useUserProfile";
import ProfileMenu from "@/components/global/ProfileMenu/ProfileMenu";
import './MenuSidebar.css';

const MenuSidebarItem = ({ icon: Icon, label, path, badge, isActive }: SidebarItemProps & { isActive?: boolean }) => (
    <Link href={path} prefetch={false} className={`sidebaritem-link ${isActive ? 'active' : ''}`}>
        <div className="icon-wrapper">
            <Icon className="icon" size={20} strokeWidth={2.5} />
            <span className="sidebaritem-span">{label}</span>
        </div>
        {badge && <div className="sidebaritem-badge">{badge}</div>}
    </Link>
);

const MenuSidebar = () => {
    const { isActive } = useActiveSidebar();
    const { user } = useUserProfile();

    const userName = user?.displayName || 'Profile';
    const avatarSrc = user?.profileImageUrl || '/icons/SoundSpaceIcon.png';
    const currentSong = user?.email || 'SoundSpace';
    const profileHref = user?.displayName
        ? `/profile/${encodeURIComponent(user.displayName)}`
        : '/profile';

    return (
        <div className="sidebar">
            <div className="sidebar-section">
                <h3 className="sidebar-header">MENU</h3>
                <div className="sidebar-items">
                    <MenuSidebarItem
                        icon={Home}
                        label="Feed"
                        path="/"
                        badge={""}
                        isActive={isActive("/")}
                    />
                    <MenuSidebarItem
                        icon={Search}
                        label="Discover"
                        path="/discovery"
                        badge={""}
                        isActive={isActive("/discovery")}
                    />
                    <MenuSidebarItem
                        icon={MessageSquare}
                        label="Messages"
                        path="/messages"
                        badge={3}
                        isActive={isActive("/messages")}
                    />
                </div>
            </div>

            <div className="sidebar-footer">
                <ProfileMenu
                    userName={userName}
                    currentSong={currentSong}
                    avatarSrc={avatarSrc}
                    profileHref={profileHref}
                />
            </div>
        </div>
    );
};

export default MenuSidebar;

import React, { useEffect, useRef, useState } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import './ProfileMenu.css';
import {logoutUser} from "@/services/auth/authService";

interface HeaderProfileMenuProps {
    userName: string;
    currentSong: string;
    avatarSrc: string;
    profileHref?: string;
    settingsHref?: string;
}

const ProfileMenu = ({
    userName,
    currentSong,
    avatarSrc,
    profileHref = '/profile',
    settingsHref = '/settings',
}: HeaderProfileMenuProps) => {
    const [showProfileMenu, setShowProfileMenu] = useState(false);
    const profileMenuRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            const target = event.target as Node;
            if (profileMenuRef.current && !profileMenuRef.current.contains(target)) {
                setShowProfileMenu(false);
            }
        };

        document.addEventListener('mousedown', handleClickOutside);
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, []);

    const handleToggleProfileMenu = () => {
        setShowProfileMenu((prev) => !prev);
    };

    const handleCloseProfileMenu = () => {
        setShowProfileMenu(false);
    };

    const handleLogout = () => {
        setShowProfileMenu(false);
        logoutUser().then(r => {});
    };

    return (
        <div className="profile-menu"
             ref={profileMenuRef}
             onClick={handleToggleProfileMenu}
        >
            <button
                type="button"
                className="profile"
                aria-label="Open profile menu"
                aria-haspopup="menu"
                aria-expanded={showProfileMenu}
            >
                <div className="profile-avatar-wrap">
                    <Image
                        src={avatarSrc}
                        alt="User avatar"
                        width={36}
                        height={36}
                        className="profile-avatar"
                    />
                </div>
                <div className="profile-info">
                    <span className="profile-name">{userName}</span>
                    <span className="profile-song">{currentSong}</span>
                </div>
            </button>

            {showProfileMenu && (
                <div className="profile-dropdown" role="menu" aria-label="Profile options">
                    <Link
                        href={profileHref}
                        className="profile-dropdown-item"
                        role="menuitem"
                        onClick={handleCloseProfileMenu}
                    >
                        Profile
                    </Link>
                    <Link
                        href={settingsHref}
                        className="profile-dropdown-item"
                        role="menuitem"
                        onClick={handleCloseProfileMenu}
                    >
                        Settings
                    </Link>
                    <button
                        type="button"
                        className="profile-dropdown-item profile-dropdown-item--danger"
                        role="menuitem"
                        onClick={handleLogout}
                    >
                        Logout
                    </button>
                </div>
            )}
        </div>
    );
};

export default ProfileMenu;

